#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

pthread_t target_thread;
volatile int signal_received = 0;

// Handler executed when SIGUSR1 is delivered to the target thread
void thread_signal_handler(int sig) {
    if (sig == SIGUSR1) {
        printf("[TID %lu] Signal SIGUSR1 received.\n", (unsigned long)pthread_self());
        signal_received = 1;
    }
}

// Function executed by the worker thread
void *worker_function(void *arg) {
    // 1. Set up the signal handling mechanism for SIGUSR1
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = thread_signal_handler;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        return NULL;
    }

    printf("[TID %lu] Worker started, waiting for signal...\n", (unsigned long)pthread_self());

    // 2. Wait until the signal handler changes the flag
    while (!signal_received) {
        // Use a small sleep to prevent busy waiting
        sleep(1);
    } 

    printf("[TID %lu] Worker exiting.\n", (unsigned long)pthread_self());
    return NULL;
}

int main() {
    int s;

    // Create the target thread
    s = pthread_create(&target_thread, NULL, worker_function, NULL);
    if (s != 0) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(s));
        return 1;
    }

    // Give worker time to initialize its handler
    sleep(2); 

    printf("[Main Thread] Sending SIGUSR1 to target thread %lu...\n", (unsigned long)target_thread);

    // Use pthread_kill to send the signal
    s = pthread_kill(target_thread, SIGUSR1);

    if (s == 0) {
        printf("[Main Thread] Signal sent successfully.\n");
    } else {
        fprintf(stderr, "[Main Thread] Error sending signal: %s\n", strerror(s));
        return 1;
    }

    // Wait for the worker thread to finish execution
    s = pthread_join(target_thread, NULL);
    if (s != 0) {
        fprintf(stderr, "Error joining thread: %s\n", strerror(s));
        return 1;
    }

    printf("[Main Thread] Program finished successfully.\n");
    return 0;
}
